save(281,dict(paragraphs=["Sudipta Mishra writes poetry and essays and has a background in dance and other arts. Her collection The Essence of Life, published by Notion Press, addresses social questions including inequality, gender discrimination and environmental concerns. Her poetry publications include The Songs of My Heart.","The poems gathered in Kabita Live return to the distance between outward appearance and inner experience. In ‘Pain’, a smile conceals anger and injury; in ‘An Escape’, successive declarations of need, desire and hope seek release from suffering. ‘In The Realm Of Permanence’ imagines blossoms, stars and a timeless world beyond everyday distractions. Together, these works explore the longing for a peace that ordinary life does not readily offer."],books=[dict(title='The Essence of Life',detail='Essays on social questions · Notion Press',url='https://notionpress.com/pdfviewer/the-essence-of-life')],sources=[source('Notion Press — The Essence of Life','https://notionpress.com/pdfviewer/the-essence-of-life','Publisher names Sudipta Mishra, identifies book as essays, ISBN9781649836892 and social themes.','search_index; direct open failed; subsequent robots restriction respected'),source('Setu — Sudipta Mishra, March 2025','https://www.setumag.com/2025/03/special-edition-sudipta-mishra.html','Poet/dancer and matching The Essence of Life/The Songs of My Heart bibliography.','search_index')],identity_match='Full name, artist/dancer background and exact two book titles match captured biography and publisher/journal sources.',poems_read=[dict(id=508,title='An Escape',coverage='Complete original',basis='Anaphoric need/desire/wait/hope/wish; memory, suffering, renunciation and Infinite Being.'),dict(id=439,title='Pain',coverage='Complete original',basis='Smiling public appearance versus concealed pain and anger.'),dict(id=356,title='In The Realm Of Permanence',coverage='Complete original',basis='Transience versus utopian timelessness; blossoms, bees, stars and trance.')],limitations=['Publisher calls The Essence of Life essays; secondary Sentinel article calls it poetic debut. Publisher genre preferred. No bestseller claim, hundred-book sole authorship, honours or current PhD status added. Poetic pain not treated as health/relationship history.'],search_queries=['Sudipta Mishra The Songs of My Heart publisher','Sudipta Mishra The Essence of Life book'],research_leads=[dict(url='https://www.sentinelassam.com/more-news/life/songs-of-my-heart-a-young-poet-from-puri-singing-in-cathartic-ecstasy-627210',access='search_index',finding='Genre wording conflicts with publisher; current degree and private-life details not imported.'),dict(url='https://www.innsaeijournal.com/wp-content/uploads/2024/01/A-Oct-Dec-23-Issue-IV-Draft.pdf',access='search_index',finding='Says coauthored100books, clarifying ambiguous captured weaved100books; total not added.')],next_action='Author/editor review; verify individual publisher listing for The Songs of My Heart.'))
